  val pc = RegInit(VecInit(Seq(L0, L0)))

  // Combinational logic for next state
  val selfNext = Wire(UInt(1.W))
  selfNext := io.select

  // State machine logic
  switch(pc(self)) {
    is(L0) {
      when(!io.pause) {
        pc(self) := L1
      }
    }
    is(L1) {
      c(self) := false.B
      pc(self) := L2
    }
    is(L2) {
      when(c(~self) === true.B) {
        pc(self) := L5
      }.otherwise {
        pc(self) := L3
      }
    }
    is(L3) {
      when(turn === self) {
        pc(self) := L2
      }.otherwise {
        c(self) := true.B
        pc(self) := L4
      }
    }
    is(L4) {
      when(turn === self) {
        c(self) := false.B
        pc(self) := L2
      }
    }
    is(L5) {
      when(!io.pause) {
        pc(self) := L6
      }
    }
    is(L6) {
      c(self) := true.B
      turn := ~self
      pc(self) := L0
    }
  }

  // Update self register
  self := selfNext

  // Connect outputs
  io.c0 := c(0)
  io.c1 := c(1)
  io.turn := turn
  io.self := self
  io.pc0 := pc(0)
  io.pc1 := pc(1)

  // ========== Formal Verification Assertions ==========

  // ---- Safety Properties ----

  // 1. Mutual Exclusion: Never both processes in critical section (L5 or L6) at the same time.
  //    This is the fundamental safety property of Dekker's algorithm.
  val inCS0 = pc(0) === L5 || pc(0) === L6
